        function calcularLeiOhm() {
            // Captura os valores de entrada
            const V = parseFloat(document.getElementById('tensão').value);
            const I = parseFloat(document.getElementById('corrente').value);
            const R = parseFloat(document.getElementById('resistencia').value);

            const resultadoDiv = document.getElementById('resultado');
            resultadoDiv.style.display = 'block';
            resultadoDiv.className = 'mt-4 p-3 text-center fs-4 fw-bold rounded bg-light';

            // Verifica quantos campos foram preenchidos
            const inputsPreenchidos = [V, I, R].filter(val => !isNaN(val) && val !== null).length;

            if (inputsPreenchidos < 2) {
                resultadoDiv.innerHTML = '<i class="fas fa-times-circle me-2"></i> Por favor, preencha pelo menos DOIS valores para calcular o terceiro.';
                resultadoDiv.classList.remove('bg-success');
                resultadoDiv.classList.add('bg-warning');
                return;
            }

            let resultadoTexto = '';
            let valorDescoberto = 0;
            let unidade = '';

            // Lógica para encontrar o valor desconhecido
            if (inputsPreenchidos === 2) {
                // Caso 1: R é desconhecido (V e I fornecidos)
                if (!isNaN(V) && !isNaN(I) && isNaN(R)) {
                    valorDescoberto = V / I;
                    unidade = 'Ω (Ohms)';
                    resultadoTexto = `Resistência (R) = ${valorDescoberto.toFixed(2)} ${unidade}`;
                } 
                // Caso 2: I é desconhecido (V e R fornecidos)
                else if (!isNaN(V) && !isNaN(R) && isNaN(I)) {
                    valorDescoberto = V / R;
                    unidade = 'A (Amperes)';
                    resultadoTexto = `Corrente (I) = ${valorDescoberto.toFixed(2)} ${unidade}`;
                } 
                // Caso 3: V é desconhecido (I e R fornecidos)
                else if (!isNaN(I) && !isNaN(R) && isNaN(V)) {
                    valorDescoberto = I * R;
                    unidade = 'V (Volts)';
                    resultadoTexto = `Tensão (V) = ${valorDescoberto.toFixed(2)} ${unidade}`;
                }
            }

            // Caso de validação: Se 3 valores foram fornecidos, apenas confirma
            if (inputsPreenchidos === 3) {
                resultadoTexto = `✅ Valores fornecidos: V=${V}V, I=${I}A, R=${R}Ω. (Verifique a consistência: ${V} == ${I}*${R}?)`;
                resultadoDiv.classList.remove('bg-warning');
                resultadoDiv.classList.add('bg-info text-white');
            }

            // Exibe o resultado
            if (resultadoTexto) {
                resultadoDiv.innerHTML = resultadoTexto;
                resultadoDiv.classList.remove('bg-warning');
                resultadoDiv.classList.add('bg-success'); // Cor verde para sucesso
            }
        }

        // Função auxiliar para cálculo de Potência
        function calcularPotencia() {
            const p_v = parseFloat(document.getElementById('p_v').value);
            const p_i = parseFloat(document.getElementById('p_i').value);
            const resultadoPotenciaDiv = document.getElementById('resultadoPotencia');

            if (isNaN(p_v) && isNaN(p_i)) {
                resultadoPotenciaDiv.innerHTML = '';
                return;
            }

            let resultado;
            let formula;

            if (!isNaN(p_v) && !isNaN(p_i)) {
                // P = V * I
                resultado = p_v * p_i;
                formula = "P = V * I";
            } else if (!isNaN(p_v) && isNaN(p_i)) {
                 resultadoPotenciaDiv.innerHTML = '⚠️ Preencha também a Corrente (A) para calcular a Potência.';
                 return;
            } else if (isNaN(p_v) && !isNaN(p_i)) {
                 // Para calcular P só com I, precisaria de R ou V, mas vamos simplificar para V*I
                 resultadoPotenciaDiv.innerHTML = '⚠️ Preencha também a Tensão (V) para calcular a Potência.';
                 return;
            }

            resultadoPotenciaDiv.innerHTML = `⚡ Potência (P) = ${resultado.toFixed(2)} W <br> (Usando a fórmula: ${formula})`;
        }
    </script>

