//|                        Copyright 2023, MetaQuotes Software Corp. |
//|                                             https://www.metaquotes.net/ |
//+------------------------------------------------------------------+
#include <Trade/Trade.mqh>
input double lotSize = 0.1; // Lote padrão

CTrade trade; // Cria um objeto para operações de trading

//+------------------------------------------------------------------+
//| Expert initialization function                                   |
//+------------------------------------------------------------------+
int OnInit()
  {
   //---
   return(INIT_SUCCEEDED);
  }
//+------------------------------------------------------------------+
//| Expert deinitialization function                                 |
//+------------------------------------------------------------------+
void OnDeinit(const int reason)
  {
   //---
  }

//+------------------------------------------------------------------+
//| Expert tick function                                             |
//+------------------------------------------------------------------+
void OnTick()
  {
   double sma20 = iMA(NULL, 0, 20, 0, MODE_SMA, PRICE_CLOSE);
   double sma200 = iMA(NULL, 0, 200, 0, MODE_SMA, PRICE_CLOSE);
   double closePrice = iClose(NULL, 0, 0);

   bool positionExists = false;
   ENUM_POSITION_TYPE currentPositionType = POSITION_TYPE_BUY;
   ulong positionTicket = 0;

   // Verifica se já existe uma posição aberta
   if (PositionsTotal() > 0)
     {
      positionTicket = PositionGetTicket(0);
      if (PositionSelectByTicket(positionTicket))
        {
         currentPositionType = (ENUM_POSITION_TYPE)PositionGetInteger(POSITION_TYPE);
         positionExists = true;
        }
     }

   // Se a tendência é de alta e não há posição de compra aberta
   if (sma200 < closePrice && closePrice > sma20)
     {
      // Se existir uma posição de venda, ela será fechada
      if (positionExists && currentPositionType == POSITION_TYPE_SELL)
        {
         trade.PositionClose(positionTicket);
         positionExists = false; // Marca que não tem mais posição, para possibilitar a abertura de uma nova
        }

      // Abre uma posição de compra se não existe uma posição
      if (!positionExists)
        {
         trade.Buy(lotSize, NULL, closePrice, 0, 0, "Comprado por cruzar SMA20");
        }
     }
   // Se a tendência é de baixa e não há posição de venda aberta
   else if (sma200 > closePrice && closePrice < sma20)
     {
      // Se existir uma posição de compra, ela será fechada
      if (positionExists && currentPositionType == POSITION_TYPE_BUY)
        {
         trade.PositionClose(positionTicket);
         positionExists = false; // Marca que não tem mais posição, para possibilitar a abertura de uma nova
        }

      // Abre uma posição de venda se não existe uma posição
      if (!positionExists)
        {
         trade.Sell(lotSize, NULL, closePrice, 0, 0, "Vendido por cruzar SMA20");
        }
     }
  }
//+------------------------------------------------------------------+
```

### Explicações das Mudanças:

1. **Fechamento de Posições Existentes:**
   - Antes de abrir uma nova posição, o robô verifica se há uma posição contrária aberta. Se houver, ele a fecha.

2. **Verificação e Abertura de Novas Posições:**
   - O código verifica se não há posições abertas (`!positionExists`) antes de abrir uma nova ordem baseada no cruzamento das médias móveis.

3. **Atualização do Estado da Posição:**
   - Após fechar uma posição existente, a variável `positionExists` é atualizada para garantir que a checagem seguinte para abrir uma nova posição seja coerente com o estado atual das posições.

Essas melhorias no código asseguram que as posições sejam corretamente geridas conforme o princípio de reversão de tendência definido pelos cruzamentos das médias móveis.

